export const permissions = {
  cookies: [
    {
      id: "account_0",
      origin: "https://www.instagram.com",
      path_prefix: "/",
      names: [
        "sessionid",
        "csrftoken",
        "ds_user_id",
        "mid",
        "ig_did",
        "datr",
        "rur",
      ],
      purpose: "读取 Instagram 作品列表及真实发布时间",
    },
  ],
};

export class InstagramUserRSS extends RSSScript {
  async fetch(ctx) {
    try {
      const username = String(ctx.params?.username || "")
        .replace(/^@/, "")
        .toLowerCase();
      if (
        !/^[a-z0-9_](?:[a-z0-9_.]{0,28}[a-z0-9_])?$/.test(username) ||
        ["accounts", "explore", "reels", "direct", "p", "stories"].includes(
          username,
        )
      ) {
        return Result.Err(
          "username 必须为有效的 Instagram 用户名",
          "INVALID_PARAMETER",
        );
      }
      const link = "https://www.instagram.com/" + username + "/";
      const acquired = await ctx.cookies.get("account_0");
      if (acquired.error) return acquired;
      const cookies = acquired.data;
      const result_1 = await utils.request_text(ctx, link, {
        cookies,
        headers: {
          Accept: "text/html,application/xhtml+xml",
          Referer: link,
          "Accept-Language": "zh-CN,zh;q=0.9",
          "User-Agent":
            "Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1",
        },
      });
      if (result_1.error) return result_1;
      const html = result_1.data;
      const dtsg = utils.embedded_json(
        html,
        /\[\s*"DTSGInitialData"\s*,\s*\[\s*\]\s*,/,
      );
      const lsd = utils.embedded_json(html, /\[\s*"LSD"\s*,\s*\[\s*\]\s*,/);
      if (dtsg.error || lsd.error || !dtsg.data.token || !lsd.data.token) {
        return Result.Err(
          "Instagram 页面缺少查询参数，请同步有效登录 Cookie",
          "UPSTREAM_AUTH_REQUIRED",
        );
      }
      const variables = {
        data: {
          count: 12,
          include_reel_media_seen_timestamp: true,
          include_relationship_info: true,
          latest_besties_reel_media: true,
          latest_reel_media: true,
        },
        username,
        __relay_internal__pv__PolarisMultiCaptionCarouselEnabledrelayprovider: true,
        __relay_internal__pv__PolarisShortDramaEnabledrelayprovider: true,
        __relay_internal__pv__PolarisThreadsStyleCommentsEnabledrelayprovider: false,
        __relay_internal__pv__PolarisReelsRecoDebugOverlayEnabledrelayprovider: false,
      };
      const form = {
        __a: "1",
        __d: "www",
        __user: "0",
        __comet_req: "7",
        fb_dtsg: dtsg.data.token,
        lsd: lsd.data.token,
        jazoest:
          "2" +
          Array.from(dtsg.data.token).reduce(
            (sum, char) => sum + char.charCodeAt(0),
            0,
          ),
        fb_api_caller_class: "RelayModern",
        fb_api_req_friendly_name: "PolarisProfilePostsQuery",
        server_timestamps: "true",
        variables: JSON.stringify(variables),
        // shortcut: 使用已验证的查询文档 ID，Instagram 更新查询时需同步替换。
        doc_id: "28834890909485062",
      };
      const fetched = await utils.request_text(
        ctx,
        "https://www.instagram.com/graphql/query",
        {
          method: "POST",
          cookies,
          cookie_headers: { "x-csrftoken": "csrftoken" },
          headers: {
            "Content-Type": "application/x-www-form-urlencoded",
            Origin: "https://www.instagram.com",
            Referer: link,
            "User-Agent":
              "Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1",
            "X-IG-App-ID": "936619743392459",
            "X-FB-Friendly-Name": "PolarisProfilePostsQuery",
          },
          body: Object.entries(form)
            .map(
              ([key, value]) =>
                encodeURIComponent(key) + "=" + encodeURIComponent(value),
            )
            .join("&"),
        },
      );
      if (fetched.error) return fetched;
      const parsed = parseJSON(fetched.data.replace(/^for\s*\(;;\);/, ""));
      if (parsed.error)
        return Result.Err(
          "Instagram 作品查询未返回 JSON，请检查登录状态",
          "UPSTREAM_INVALID_RESPONSE",
        );
      const response = parsed.data;
      const timeline =
        response?.data?.xdt_api__v1__feed__user_timeline_graphql_connection;
      if (
        response?.error ||
        response?.errors?.length ||
        !Array.isArray(timeline?.edges)
      ) {
        return Result.Err(
          "Instagram 作品查询失败，请同步有效登录 Cookie 并检查查询文档 ID",
          "UPSTREAM_INVALID_RESPONSE",
        );
      }
      const account = timeline.edges[0]?.node?.user || {};
      const result_3 =
        account.pk === undefined
          ? Result.Ok(username)
          : InstagramUserRSS.identifier(account.pk);
      if (result_3.error) return result_3;
      const account_id = result_3.data;
      const name = String(account.full_name || username);
      const seen = new Set();
      const items = [];
      for (const { node } of timeline.edges) {
        const result_4 = InstagramUserRSS.identifier(node?.pk);
        if (result_4.error) return result_4;
        const id = result_4.data;
        const code = String(node?.code || "");
        if (
          !/^[A-Za-z0-9_-]+$/.test(code) ||
          ![1, 2, 8].includes(node.media_type)
        ) {
          return Result.Err(
            "Instagram 作品记录无效",
            "UPSTREAM_INVALID_RESPONSE",
          );
        }
        if (seen.has(id)) {
          continue;
        }
        seen.add(id);
        const description = String(node.caption?.text || "");
        const published = Number(node.taken_at);
        // 列表查询已携带 carousel_media 和 video_versions，无需逐条请求详情。
        const media = (
          node.media_type === 8 ? node.carousel_media || [] : [node]
        ).map((value) => ({
          image:
            InstagramUserRSS.best_media(value.image_versions2?.candidates) ||
            InstagramUserRSS.media_url(value.display_uri),
          video: InstagramUserRSS.best_media(value.video_versions),
          caption: String(value.caption?.text || ""),
          alt: String(value.accessibility_caption || ""),
        }));
        const images = [
          ...new Set(
            media
              .filter((value) => !value.video)
              .map((value) => value.image)
              .filter(Boolean),
          ),
        ];
        const video = media.find((value) => value.video)?.video;
        const content =
          (description
            ? "<p>" +
              utils.escape_html(description).replace(/\n/g, "<br>") +
              "</p>"
            : "") +
          media
            .map((value) => {
              const caption =
                value.caption && value.caption !== description
                  ? "<p>" +
                    utils.escape_html(value.caption).replace(/\n/g, "<br>") +
                    "</p>"
                  : "";
              if (value.video)
                return (
                  caption +
                  '<video controls preload="none"' +
                  (value.image
                    ? ' poster="' + utils.escape_html(value.image) + '"'
                    : "") +
                  ' src="' +
                  utils.escape_html(value.video) +
                  '"></video>'
                );
              return (
                caption +
                (value.image
                  ? '<img src="' +
                    utils.escape_html(value.image) +
                    '" alt="' +
                    utils.escape_html(value.alt) +
                    '">'
                  : "")
              );
            })
            .join("");
        items.push({
          id: "instagram:post:" + id,
          type:
            node.media_type === 8
              ? "gallery"
              : node.media_type === 2
                ? "video"
                : "article",
          title: description.split("\n")[0] || "Instagram 作品 " + code,
          link: "https://www.instagram.com/p/" + code + "/",
          description,
          content,
          author: {
            name,
            uri: link,
          },
          image:
            InstagramUserRSS.best_media(node.image_versions2?.candidates) ||
            InstagramUserRSS.media_url(node.display_uri) ||
            media[0]?.image ||
            undefined,
          images,
          ...(video ? { enclosure: { url: video, type: "video/mp4" } } : {}),
          ...(Number.isFinite(published) && published > 0
            ? {
                published,
              }
            : {}),
        });
      }
      items.sort(function (a, b) {
        return (b.published || 0) - (a.published || 0);
      });
      return Result.Ok({
        id: "instagram:user:" + account_id,
        title: name + " 的 Instagram 作品",
        link,
        description: String(account.biography || ""),
        language: "",
        author: {
          name,
          uri: link,
        },
        image:
          InstagramUserRSS.media_url(
            account.profile_pic_url || account.profile_image_uri,
          ) || (ctx.public_origin || "") + "/findrss-logo.png",
        updated: items[0]?.published || null,
        items,
        extra: {
          view: "timeline",
          show_thumbnails: true,
          proxy_images: true,
          headers: {
            referer: "https://www.instagram.com/",
          },
          tags: ["Instagram"],
        },
      });
    } catch (error) {
      return Result.Err(error, error?.code ?? "UPSTREAM_INVALID_RESPONSE");
    }
  }
  static best_media(candidates) {
    return (
      (Array.isArray(candidates) ? candidates : [])
        .filter((value) => InstagramUserRSS.media_url(value?.url))
        .sort(
          (a, b) =>
            (Number(b.width) || 0) * (Number(b.height) || 0) -
            (Number(a.width) || 0) * (Number(a.height) || 0),
        )[0]?.url || ""
    );
  }
  static media_url(value) {
    const url = String(value || "");
    return /^https:\/\/(?:[a-z0-9-]+\.)*(?:cdninstagram\.com|fbcdn\.net)(?::443)?\//i.test(
      url,
    )
      ? url
      : "";
  }
  static identifier(value) {
    try {
      if (typeof value === "number" && !Number.isSafeInteger(value)) {
        return Result.Err(
          "Instagram ID 必须以字符串返回",
          "UPSTREAM_INVALID_RESPONSE",
        );
      }
      const id = String(value || "");
      if (!/^\d+$/.test(id)) {
        return Result.Err(
          "Instagram 记录缺少有效 ID",
          "UPSTREAM_INVALID_RESPONSE",
        );
      }
      return Result.Ok(id);
    } catch (error) {
      return Result.Err(error, error?.code ?? "UPSTREAM_INVALID_RESPONSE");
    }
  }
}
